// ─── EQ2 CLASSES ────────────────────────────────────────────────────────────
export interface ClassAbility {
  id: string; name: string; description: string;
  type: "combatArt" | "spell" | "heroicArt" | "proc";
  damageType?: string; powerCost: number; cooldown: number; damage?: number;
  damageScale?: number; healAmount?: number; effect?: string;
  icon: string; autocast: boolean; levelRequired: number;
}

export interface ClassDefinition {
  id: string; name: string; archetype: "Fighter" | "Scout" | "Mage" | "Priest";
  subclassOf?: string; description: string; lore: string;
  primaryStat: string; armorType: "plate" | "chain" | "leather" | "cloth";
  role: "tank" | "dps" | "healer" | "support" | "hybrid";
  abilities: ClassAbility[]; spriteId: string; allowedAlignments: string[];
  statBonuses: { strength?: number; agility?: number; stamina?: number; intelligence?: number; wisdom?: number; charisma?: number; };
}

